14	public class EnsureCityCapacity {
15	
16	    private static final int MAX_OWNERS_PER_CITY = 50;
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = normalize(owner.getCity());
21	        long count = ownerRepository.findAll().stream()
22	                .filter(existing -> !existing.getId().equals(owner.getId()))
23	                .filter(existing -> normalize(existing.getCity()).equals(city))
24	                .count();
25	        if (count >= MAX_OWNERS_PER_CITY) {
26	            throw new CityAtCapacityException(
27	                    "The city " + owner.getCity() + " already has " + MAX_OWNERS_PER_CITY + " or more owners");
28	        }
29	    }
30	
31	    private static String normalize(String value) {
32	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
33	    }
34	}
