3	/**
4	 * Thrown by {@link org.springframework.samples.petclinic.rest.function.owner.EnsureUniqueEmail}
5	 * when the lower-cased email of an owner being created is already used by another owner.
6	 * Handled by {@link DuplicateEmailExceptionHandler}, which responds 409.
7	 */
