1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
39	    @Mapping(target = "locality", expression = "java(locality(owner))")
40	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
41	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
42	    public abstract OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
46	     * present (non-null and non-blank), otherwise {@code PHONE}.
47	     */
48	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
49	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
50	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
51	    }
52	
53	    /**
54	     * Fixed city-to-region table: the owner's canonical region derived from its city.
55	     */
56	    static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
57	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
58	
59	    /**
60	     * Derives the owner's {@code locality} from its city using the fixed city-to-region
61	     * table ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), returning the canonical
62	     * region string, or {@code "UNKNOWN"} when the city is not in the table.
63	     */
64	    protected String locality(Owner owner) {
65	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
66	    }
67	
68	    /**
69	     * The membership level is capped at this value; level 4 is reserved for tenure.
70	     */
71	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
72	
73	    /**
74	     * Returns the owner's membership level, a number from 1 to
75	     * {@value #MAX_MEMBERSHIP_LEVEL} assigned at creation: it starts at 1, gains 1 when
76	     * an email address is present, gains 1 when the owner has no namesakes
77	     * (namesakeCount is 0), and is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is
78	     * reserved for tenure).
79	     */
80	    public static int membershipLevel(Owner owner) {
81	        int level = 1;
82	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
83	        if (hasEmail) {
84	            level++;
85	        }
86	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
87	        if (noNamesakes) {
88	            level++;
89	        }
90	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
91	    }
92	
93	    /**
94	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
95	     * the registrationDate year (e.g. 'SMI-0007-M26'). Returns {@code null} when either the
96	     * customer code or the registration date is absent (e.g. legacy seed owners).
97	     */
98	    protected String membershipNumber(Owner owner) {
99	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
100	            return null;
101	        }
102	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
103	    }
104	
105	    /**
106	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
107	     * been created for this owner's {@code registrationDate}, using the same per-day
108	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
109	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
110	     */
111	    protected boolean bulkSignupWarning(Owner owner) {
112	        LocalDate registrationDate = owner.getRegistrationDate();
113	        if (registrationDate == null) {
114	            return false;
115	        }
116	        long count = ownerRepository.findAll().stream()
117	                .filter(existing -> !existing.getId().equals(owner.getId()))
118	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
119	                .count();
120	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
121	    }
122	
123	    public abstract Owner toOwner(OwnerDto ownerDto);
124	
125	    @Mapping(target = "id", ignore = true)
126	    @Mapping(target = "pets", ignore = true)
127	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
128	
129	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
130	
131	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
132	
133	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
134	        OwnerPageDto ownerPageDto = new OwnerPageDto();
135	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
136	        ownerPageDto.setPage(ownerPage.getNumber());
137	        ownerPageDto.setSize(ownerPage.getSize());
138	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
139	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
140	        return ownerPageDto;
141	    }
142	}
